import java.util.*;

public class Main {
    // Abstraction: callers depend only on this contract
    interface Shape { double area(); }

    // Inheritance: Circle and Rect both reuse the Shape type
    static class Circle implements Shape {
        private final double r; // Encapsulation: private state
        Circle(double r) {
            if (r <= 0) throw new IllegalArgumentException("r must be > 0");
            this.r = r;
        }
        public double area() { return Math.round(Math.PI * r * r * 100) / 100.0; }
    }

    static class Rect implements Shape {
        private final double w, h;
        Rect(double w, double h) { this.w = w; this.h = h; }
        public double area() { return w * h; }
    }

    public static void main(String[] args) {
        List<Shape> shapes = List.of(new Circle(1), new Rect(3, 4));
        // Polymorphism: one call, different behaviour per object
        for (Shape s : shapes) {
            System.out.println(s.getClass().getSimpleName() + " area = " + s.area());
        }
        try {
            new Circle(-1); // the invariant is guarded by the constructor
        } catch (IllegalArgumentException e) {
            System.out.println("Rejected: " + e.getMessage());
        }
    }
}

public class Main {
    // Abstraction: a simple contract, provider details hidden
    interface PaymentGateway { String charge(int cents); }

    static class FakeProvider implements PaymentGateway {
        public String charge(int cents) { return "charged " + cents + " cents"; }
    }

    // Encapsulation: balance can only change through guarded methods
    static class BankAccount {
        private int balance;
        BankAccount(int start) { balance = start; }
        boolean withdraw(int amt) {
            if (amt <= 0 || amt > balance) return false; // invariant: balance >= 0
            balance -= amt;
            return true;
        }
        int balance() { return balance; }
    }

    public static void main(String[] args) {
        BankAccount acc = new BankAccount(100);
        System.out.println("withdraw 30: " + acc.withdraw(30) + ", balance " + acc.balance());
        System.out.println("withdraw 500: " + acc.withdraw(500) + ", balance " + acc.balance());
        PaymentGateway g = new FakeProvider(); // caller knows only the interface
        System.out.println(g.charge(2500));
    }
}

public class Main {
    static class Animal {
        String sound() { return "..."; }
        String greet(Object o) { return "Animal.greet(Object)"; }
        String greet(String s) { return "Animal.greet(String)"; }
    }
    static class Dog extends Animal {
        @Override String sound() { return "Woof"; }   // overriding: chosen at runtime
        @Override String greet(Object o) { return "Dog.greet(Object)"; }
    }

    public static void main(String[] args) {
        Animal a = new Dog();          // declared type Animal, real type Dog
        Object o = "hello";            // declared type Object, real type String
        System.out.println(a.sound());       // runtime type decides: Woof
        // Overload picked at compile time from the declared type Object,
        // then the JVM dispatches that signature on the real class Dog.
        System.out.println(a.greet(o));      // Dog.greet(Object)
        System.out.println(a.greet("hello")); // Animal.greet(String)
        print(1);                   // widening int->long beats boxing
        print(Integer.valueOf(1));  // Integer -> Object (subtype) beats unboxing
    }
    static void print(long x)    { System.out.println("long " + x); }
    static void print(Object x)  { System.out.println("Object " + x); }
}

public class Main {
    static class Parent {
        static String who() { return "Parent.static"; }
        private String secret() { return "Parent.private"; }
        String callSecret() { return secret(); }   // always Parent's private
        String name() { return "Parent.name"; }
    }
    static class Child extends Parent {
        static String who() { return "Child.static"; }   // hides, not overrides
        private String secret() { return "Child.private"; } // unrelated new method
        @Override String name() { return "Child.name"; }  // a real override
    }

    public static void main(String[] args) {
        Parent p = new Child();
        // Static: chosen by the declared type at compile time
        System.out.println(Parent.who() + " | " + Child.who());
        // A null reference still works for static calls: no object needed
        Parent nothing = null;
        System.out.println(nothing.who());
        // Private: the parent's code keeps calling its own private method
        System.out.println(p.callSecret());
        // Instance method: runtime type wins
        System.out.println(p.name());
        // 'final' methods cannot be overridden: declaring one in Child would not compile
    }
}

public class Main {
    // Interface: a capability, no instance state
    interface Greeter {
        String name();
        default String greet() { return "Hello, " + name(); }
    }

    // Abstract class: shared state + fixed algorithm (Template Method)
    static abstract class Report {
        private final String title;           // state allowed here
        Report(String title) { this.title = title; }
        final String render() {               // the fixed algorithm
            return "== " + title + " ==\n" + body() + "\n-- end --";
        }
        protected abstract String body();     // the step subclasses supply
    }

    static class SalesReport extends Report implements Greeter {
        SalesReport() { super("Sales"); }
        protected String body() { return "total = 120"; }
        public String name() { return "sales team"; }
    }

    public static void main(String[] args) {
        SalesReport r = new SalesReport();
        System.out.println(r.render());
        System.out.println(r.greet());
        // One superclass, but many interfaces can be combined on one class.
        System.out.println(r instanceof Report);
        System.out.println(r instanceof Greeter);
    }
}

public class Main {
    interface A { default String hi() { return "A.hi"; } }
    interface B extends A { default String hi() { return "B.hi"; } } // more specific
    interface C { default String hi() { return "C.hi"; } }

    static class Base { public String hi() { return "Base.hi"; } }

    static class X implements A, B { }                       // rule 2: B wins over A
    static class Y extends Base implements A { }             // rule 1: class wins
    static class Z implements B, C {                         // rule 3: must resolve
        public String hi() { return B.super.hi() + "+" + C.super.hi(); }
    }

    public static void main(String[] args) {
        System.out.println("X: " + new X().hi());
        System.out.println("Y: " + new Y().hi());
        System.out.println("Z: " + new Z().hi());
        // Without the override in Z, javac reports an inherited-defaults conflict.
    }
}

public class Main {
    interface Op { int apply(int x); }
    static class Inc implements Op { public int apply(int x) { return x + 1; } }
    static class Dbl implements Op { public int apply(int x) { return x * 2; } }
    static class Neg implements Op { public int apply(int x) { return -x; } }

    // Each call goes through the receiver's class (vtable/itable lookup,
    // or inlined by the JIT when only one or two types are seen).
    static long run(Op[] ops, int rounds) {
        long sum = 0;
        for (int r = 0; r < rounds; r++)
            for (Op op : ops) sum += op.apply(r & 7);
        return sum;
    }

    public static void main(String[] args) {
        Op[] mono = { new Inc(), new Inc(), new Inc() };            // monomorphic site
        Op[] mega = { new Inc(), new Dbl(), new Neg() };            // megamorphic site
        System.out.println("monomorphic result = " + run(mono, 1000));
        System.out.println("megamorphic result = " + run(mega, 1000));
        Op o = new Dbl();
        System.out.println("runtime class = " + o.getClass().getSimpleName()
            + ", apply(21) = " + o.apply(21));
    }
}

import java.util.*;

public class Main {
    static class Bad {
        final int id;
        Bad(int id) { this.id = id; }
        @Override public boolean equals(Object o) {      // equals without hashCode
            return o instanceof Bad b && b.id == id;
        }
    }
    static class Good extends Bad {
        Good(int id) { super(id); }
        @Override public int hashCode() { return Integer.hashCode(id); } // same field
    }

    public static void main(String[] args) {
        Map<Bad, String> m1 = new HashMap<>();
        m1.put(new Bad(1), "one");
        System.out.println("Bad get : " + m1.get(new Bad(1)));   // usually null
        Map<Bad, String> m2 = new HashMap<>();
        m2.put(new Good(1), "one");
        System.out.println("Good get: " + m2.get(new Good(1)));  // one
        Set<Bad> s = new HashSet<>(List.of(new Good(2)));
        s.add(new Good(2));
        System.out.println("Good set size: " + s.size());        // 1
    }
}

import java.util.*;

public class Main {
    // Inheritance: overrides add and addAll to count insertions
    static class CountingSet extends HashSet<String> {
        int count = 0;
        @Override public boolean add(String s) { count++; return super.add(s); }
        @Override public boolean addAll(Collection<? extends String> c) {
            count += c.size();
            return super.addAll(c);   // HashSet's addAll calls add() -> counts twice
        }
    }

    // Composition: wrap a Set and forward the calls
    static class CountingWrapper {
        private final Set<String> set = new HashSet<>();
        int count = 0;
        void addAll(Collection<String> c) { count += c.size(); set.addAll(c); }
    }

    public static void main(String[] args) {
        List<String> in = List.of("a", "b", "c");
        CountingSet bad = new CountingSet();
        bad.addAll(in);
        System.out.println("added 3, inheritance counts " + bad.count);
        CountingWrapper good = new CountingWrapper();
        good.addAll(in);
        System.out.println("added 3, composition counts " + good.count);
    }
}

import java.util.*;

public class Main {
    // Properly immutable: final class, private final fields, defensive copies
    static final class Team {
        private final String name;
        private final List<String> members;
        Team(String name, List<String> members) {
            this.name = name;
            this.members = List.copyOf(members);   // defensive copy
        }
        List<String> members() { return members; }
        String name() { return name; }
    }

    public static void main(String[] args) {
        final List<String> list = new ArrayList<>();
        list.add("x");                 // allowed: the object is mutable
        System.out.println("final list still changes: " + list);
        // list = new ArrayList<>();   // would not compile: reference is final

        List<String> src = new ArrayList<>(List.of("ann", "bo"));
        Team t = new Team("core", src);
        src.add("cy");                 // does not leak into the Team
        System.out.println("team members: " + t.members());
        try {
            t.members().add("zed");
        } catch (UnsupportedOperationException e) {
            System.out.println("team list is read-only");
        }
    }
}

public class Main {
    static class Parent {
        Parent() {
            System.out.println("Parent ctor calls describe()");
            describe();               // virtual call: dispatches to Child
        }
        void describe() { System.out.println("Parent.describe"); }
    }
    static class Child extends Parent {
        private String label = "ready";   // runs only AFTER Parent() returns
        private final int size = 5;       // constant: inlined by the compiler
        Child() { super(); System.out.println("Child ctor done, label=" + label); }
        @Override void describe() {
            System.out.println("Child.describe label=" + label + ", size=" + size);
        }
    }

    public static void main(String[] args) {
        new Child();
        // Fix: make the called method private/final/static, or pass data in
        // through constructor arguments instead of relying on subclass fields.
    }
}

public class Main {
    interface Flyer { default String move() { return "fly"; } String name(); }
    interface Swimmer { default String move() { return "swim"; } }

    // Two "parents" of type and behaviour; no shared state, so no diamond of fields
    static class Duck implements Flyer, Swimmer {
        public String name() { return "Duck"; }
        public String move() {                       // explicit resolution
            return Flyer.super.move() + " and " + Swimmer.super.move();
        }
    }

    // State is shared through composition, not inheritance
    static class Engine { int hp = 90; }
    static class Boat {
        private final Engine engine = new Engine();  // has-a
        String info() { return "engine " + engine.hp + " hp"; }
    }

    public static void main(String[] args) {
        Duck d = new Duck();
        System.out.println(d.name() + " can " + d.move());
        System.out.println("Boat: " + new Boat().info());
        System.out.println("Duck is Flyer: " + (d instanceof Flyer)
            + ", Swimmer: " + (d instanceof Swimmer));
    }
}

public class Main {
    static class Rectangle {
        protected int w, h;
        void setWidth(int w) { this.w = w; }
        void setHeight(int h) { this.h = h; }
        int area() { return w * h; }
    }
    // Violates LSP: it changes the behaviour callers rely on
    static class Square extends Rectangle {
        @Override void setWidth(int x) { w = x; h = x; }
        @Override void setHeight(int x) { w = x; h = x; }
    }

    // Caller written against Rectangle: expects width and height are independent
    static int stretch(Rectangle r) {
        r.setWidth(5);
        r.setHeight(4);
        return r.area();     // expected 20
    }

    public static void main(String[] args) {
        System.out.println("Rectangle area: " + stretch(new Rectangle()));
        System.out.println("Square    area: " + stretch(new Square()));
        // Fix: make shapes immutable, or give Square and Rectangle a common
        // interface Shape { int area(); } instead of one extending the other.
    }
}

import java.util.*;

public class Main {
    static class Team implements Cloneable {
        String name;
        List<String> members = new ArrayList<>();
        Team(String name) { this.name = name; }
        Team(Team other) {                         // copy constructor: explicit deep copy
            this.name = other.name;
            this.members = new ArrayList<>(other.members);
        }
        @Override public Team clone() {
            try { return (Team) super.clone(); }   // shallow: shares the list
            catch (CloneNotSupportedException e) { throw new AssertionError(e); }
        }
    }

    public static void main(String[] args) {
        Team a = new Team("core");
        a.members.add("ann");

        Team shallow = a.clone();
        shallow.members.add("bo");                 // also changes a!
        System.out.println("after clone()   a = " + a.members);

        Team b = new Team("core");
        b.members.add("ann");
        Team deep = new Team(b);
        deep.members.add("bo");
        System.out.println("after copy ctor b = " + b.members);

        int[] arr = {1, 2, 3};
        int[] c = arr.clone();                     // arrays: clone is fine
        c[0] = 99;
        System.out.println("array " + Arrays.toString(arr) + " copy " + Arrays.toString(c));
    }
}

public class Main {
    // Closed set of types: the compiler knows every case
    sealed interface Expr permits Num, Add, Mul {}
    record Num(int v) implements Expr {}
    record Add(Expr l, Expr r) implements Expr {}
    record Mul(Expr l, Expr r) implements Expr {}

    // New operation: just add another switch. No default needed: exhaustive.
    static int eval(Expr e) {
        return switch (e) {
            case Num n -> n.v();
            case Add(Expr l, Expr r) -> eval(l) + eval(r);
            case Mul(Expr l, Expr r) -> eval(l) * eval(r);
        };
    }

    static String show(Expr e) {
        return switch (e) {
            case Num n -> String.valueOf(n.v());
            case Add a -> "(" + show(a.l()) + " + " + show(a.r()) + ")";
            case Mul m -> show(m.l()) + " * " + show(m.r());
        };
    }

    public static void main(String[] args) {
        Expr e = new Mul(new Add(new Num(2), new Num(3)), new Num(4));
        System.out.println(show(e) + " = " + eval(e));
    }
}
